function withDefaults(obj, defaults) {
  const result = { ...obj };
  for (const key in defaults) {
    if (!Object.prototype.hasOwnProperty.call(defaults, key)) continue;
    if (result[key] === null || result[key] === undefined) {
      result[key] = defaults[key];
    }
  }
  return result;
}
